CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tenants (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, asset_key TEXT NOT NULL, asset_type TEXT NOT NULL DEFAULT 'boiler', display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(tenant_id, asset_key));
CREATE TABLE IF NOT EXISTS incoming_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, asset_id UUID REFERENCES assets(id) ON DELETE SET NULL, asset_key TEXT NOT NULL, source TEXT NOT NULL, event_type TEXT NOT NULL, title TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN ('Critical','Warning','Info')), event_value DOUBLE PRECISION, threshold_value DOUBLE PRECISION, unit TEXT, status TEXT NOT NULL DEFAULT 'New' CHECK(status IN ('New','Reviewed')), occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_events_tenant_time ON incoming_events(tenant_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_tenant_severity ON incoming_events(tenant_id, severity, status);
CREATE TABLE IF NOT EXISTS recipients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, full_name TEXT NOT NULL, role TEXT NOT NULL, email TEXT, phone TEXT, channels TEXT[] NOT NULL DEFAULT ARRAY['In-app']::TEXT[], active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(email IS NOT NULL OR phone IS NOT NULL));
CREATE TABLE IF NOT EXISTS routing_policies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name TEXT NOT NULL, event_type TEXT, severity TEXT CHECK(severity IN ('Critical','Warning','Info')), channels TEXT[] NOT NULL DEFAULT ARRAY['In-app']::TEXT[], enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS routing_policy_recipients (policy_id UUID NOT NULL REFERENCES routing_policies(id) ON DELETE CASCADE, recipient_id UUID NOT NULL REFERENCES recipients(id) ON DELETE CASCADE, PRIMARY KEY(policy_id, recipient_id));
CREATE TABLE IF NOT EXISTS notification_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, event_id UUID NOT NULL REFERENCES incoming_events(id) ON DELETE CASCADE, recipient_id UUID REFERENCES recipients(id) ON DELETE SET NULL, channel TEXT NOT NULL CHECK(channel IN ('Email','SMS','In-app')), destination TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Queued' CHECK(status IN ('Queued','Sent','Delivered','Failed','Suppressed')), attempt_count INTEGER NOT NULL DEFAULT 0, provider_message_id TEXT, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_deliveries_tenant_status ON notification_deliveries(tenant_id, status, created_at DESC);
CREATE TABLE IF NOT EXISTS audit_log (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details JSONB NOT NULL DEFAULT '{}'::JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO tenants(name) SELECT 'Boiler Demo Tenant' WHERE NOT EXISTS(SELECT 1 FROM tenants WHERE name='Boiler Demo Tenant');
